<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {api,ApiError} from '../api'
import type {TaskCategory} from '../taskCategories'
import {formatMediaBytes} from '../library'
import {validCenterPage,validPauseReceipt,canDeleteCenterTask,validCenterDelete,centerStateLabels,centerPhaseLabels,centerActionLabel,centerProgress,centerEta,centerRetrySummary,centerScanScope,centerScanHint,registeredScan,validScanDetail,type ScanDetail,type CenterKind,type CenterStatus,type CenterPage,type CenterRow,type PauseReceipt} from '../taskCenter'
import UploadTasks from './UploadTasks.vue'
import DownloadTasks from './DownloadTasks.vue'
import DownloadBatches from './DownloadBatches.vue'
import RuleDownloadTasks from './RuleDownloadTasks.vue'
const props=withDefaults(defineProps<{authorized:boolean;available:boolean;accountId:string|null;active?:boolean;category?:TaskCategory;refreshVersion?:number}>(),{active:true})
const emit=defineEmits<{accessError:[cause:ApiError];'update:category':[value:TaskCategory]}>()
const categoryKind=(category:TaskCategory|undefined):CenterKind=>category==='upload'?'upload':category==='scan'?'scan':category==='download'||category==='batches'?'download':'all'
const selected=ref<CenterKind>(categoryKind(props.category)),status=ref<CenterStatus>('all'),offset=ref(0),limit=20
const page=ref<CenterPage|null>(null),loading=ref(false),error=ref(''),notice=ref(''),busy=ref(''),detail=ref<CenterRow|null>(null),detailRefresh=ref(0)
const cachedDetails=ref<CenterRow[]>([])
const deleteDialog=ref<HTMLDialogElement|null>(null),deleteConfirmation=ref<{row:CenterRow;generation:number;account:string|null}|null>(null)
const deleteUnknown=ref<Record<string,boolean>>({})
const scanDetails=ref<Record<string,ScanDetail>>({}),scanErrors=ref<Record<string,string>>({}),scanLoading=ref('')
let scanRequest=0
const pauseOperation=ref(''),pauseReceipt=ref<PauseReceipt|null>(null),pauseUnknown=ref(false),pausePending=ref(false)
let disposed=false,generation=0,actionRequest=0,pending=false,queued=false,timer:ReturnType<typeof setTimeout>|undefined
const tabs:{id:CenterKind;label:string}[]=[{id:'all',label:'全部'},{id:'upload',label:'上传'},{id:'download',label:'下载'},{id:'scan',label:'扫描'}]
const statuses:{id:Exclude<CenterStatus,'all'>;label:string;description?:string}[]=[{id:'active',label:'进行中'},{id:'attention',label:'需要处理'},{id:'waiting',label:'等待 / 暂停'},{id:'completed',label:'已结束',description:'包括已完成和已取消的任务；以每行具体状态为准。'}]
const ready=()=>!disposed&&props.active!==false&&props.authorized&&props.available&&!!props.accountId
const current=(context:number,account:string|null)=>ready()&&context===generation&&account===props.accountId
const pageNumber=computed(()=>Math.floor(offset.value/limit)+1),pageCount=computed(()=>Math.max(1,Math.ceil((page.value?.total??0)/limit)))
function stop(){clearTimeout(timer);timer=undefined}
function access(cause:unknown){if(cause instanceof ApiError&&[401,403].includes(cause.status))emit('accessError',cause)}
function schedule(){stop();if(ready()&&!busy.value&&!pausePending.value&&!pending&&!deleteConfirmation.value)timer=setTimeout(()=>void load(true),3000)}
async function load(quiet=false){
  if(!ready())return;if(pending){queued=true;return}pending=true;stop();const context=generation,account=props.accountId,start=offset.value,kind=selected.value,filter=status.value
  if(!quiet)loading.value=true
  try{const result=await api<CenterPage>(`/transfers/center?kind=${kind}&status=${filter}&limit=${limit}&offset=${start}`)
    if(!current(context,account))return;if(!validCenterPage(result))throw new Error('任务汇总回执无法确认，请刷新核对。')
    if(start>0&&start>=result.total){offset.value=Math.max(0,Math.floor(Math.max(0,result.total-1)/limit)*limit);queued=true;return}
    page.value=result;error.value='';deleteUnknown.value={};if(deleteConfirmation.value&&!currentDeleteRow(deleteConfirmation.value.row)){clearDeleteConfirmation();notice.value='任务状态已变化，请重新核对后删除。'}cachedDetails.value=cachedDetails.value.map(saved=>result.items.find(row=>row.category===saved.category&&row.id===saved.id)??saved);if(detail.value){const fresh=result.items.find(row=>row.category===detail.value!.category&&row.id===detail.value!.id);if(fresh)detail.value=fresh}
  }catch(cause){if(current(context,account)){error.value=cause instanceof Error?cause.message:'读取任务未完成';access(cause)}}
  finally{pending=false;if(current(context,account))loading.value=false;if(queued&&ready()){queued=false;void load()}else schedule()}
}
function select(kind:CenterKind){if(!tabs.some(tab=>tab.id===kind))return;clearDeleteConfirmation();selected.value=kind;offset.value=0;generation++;page.value=null;detail.value=null;void load();emit('update:category',kind)}
function filter(value:CenterStatus){clearDeleteConfirmation();status.value=value;offset.value=0;generation++;page.value=null;detail.value=null;void load()}
function paginate(delta:number){if(loading.value)return;clearDeleteConfirmation();offset.value=Math.max(0,Math.min((pageCount.value-1)*limit,offset.value+delta*limit));generation++;void load()}
const detailKey=(row:CenterRow)=>row.category+':'+row.id
function scanHint(row:CenterRow){const saved=scanDetails.value[detailKey(row)];return centerScanHint(saved?{...row,state:saved.state,actions:saved.current?saved.actions:[]}:row)}
function scanState(row:CenterRow){const state=scanDetails.value[detailKey(row)]?.state??row.state;return centerStateLabels[state]??state}
async function loadScanDetail(row:CenterRow){
  if(!registeredScan(row)||!ready()||!detailActive(row)||scanLoading.value===detailKey(row))return
  const key=detailKey(row),ticket=++scanRequest,context=generation,account=props.accountId
  scanLoading.value=key;delete scanErrors.value[key]
  const valid=()=>ticket===scanRequest&&current(context,account)&&detailActive(row)
  try{const result=await api<unknown>('/transfers/center/scans/'+encodeURIComponent(row.id));if(!valid())return
    if(!validScanDetail(result,row))throw new Error('扫描详情身份或修订号无法确认，请手动重新核对。')
    scanDetails.value[key]=result
  }catch(cause){if(valid()){scanErrors.value[key]=cause instanceof ApiError&&[400,404].includes(cause.status)?'未找到这条扫描的已登记历史，可能属于旧版导入记录。请回原面板核对，当前不会认领或恢复扫描。':(cause instanceof Error?cause.message:'扫描详情读取未完成。');access(cause)}}
  finally{if(ticket===scanRequest)scanLoading.value=''}
}
function showDetail(row:CenterRow){if(!cachedDetails.value.some(saved=>saved.id===row.id&&saved.category===row.category))cachedDetails.value.push(row);detail.value=row;void loadScanDetail(row);void nextTick().then(()=>{if(detailActive(row)&&typeof document!=='undefined')document.getElementById('task-detail-'+row.category+'-'+row.id)?.focus()})}
function closeDetail(){const row=detail.value;detail.value=null;scanRequest++;scanLoading.value='';void nextTick().then(()=>{if(row&&typeof document!=='undefined')document.getElementById('task-open-'+row.category+'-'+row.id)?.focus()})}
function detailActive(row:CenterRow){return props.active!==false&&detail.value?.id===row.id&&detail.value?.category===row.category}
function openDetail(row:CenterRow){if(detail.value?.id===row.id&&detail.value?.category===row.category)closeDetail();else showDetail(row)}
function confirmsAction(result:unknown,row:CenterRow){if(!result||typeof result!=='object'||!('item' in result)||!result.item||typeof result.item!=='object')return false;const item=result.item as {id?:unknown;state?:unknown;rule?:{id?:unknown}};return item.id===row.id&&typeof item.state==='string'||item.rule?.id===row.id}
function currentDeleteRow(saved:CenterRow){return page.value?.items.find(row=>row.id===saved.id&&row.category===saved.category&&row.state===saved.state&&row.updatedAt===saved.updatedAt&&canDeleteCenterTask(row))}
function clearDeleteConfirmation(){deleteDialog.value?.close();deleteConfirmation.value=null}
function cancelDelete(){clearDeleteConfirmation();schedule()}
async function prepareDelete(row:CenterRow){
  if(!ready()||busy.value||pausePending.value||deleteUnknown.value[detailKey(row)])return
  const fresh=currentDeleteRow(row);if(!fresh)return
  stop();deleteConfirmation.value={row:JSON.parse(JSON.stringify(fresh)) as CenterRow,generation,account:props.accountId};const confirmation=deleteConfirmation.value
  await nextTick()
  if(deleteConfirmation.value===confirmation&&current(confirmation.generation,confirmation.account)&&currentDeleteRow(confirmation.row))deleteDialog.value?.showModal()
}
async function confirmDelete(){
  const confirmation=deleteConfirmation.value
  if(!confirmation||!ready()||busy.value||pausePending.value)return
  const fresh=currentDeleteRow(confirmation.row)
  clearDeleteConfirmation()
  if(!current(confirmation.generation,confirmation.account)||!fresh){notice.value='任务状态已变化，请重新核对后删除。';schedule();return}
  await performAction(fresh,'delete')
}
function actionNotice(row:CenterRow,verb:string){
  if(row.kind==='scan'&&verb==='pause')return '暂停已受理；当前有界读取结束后停止后续步骤，并保留检查点。'
  if(row.kind==='scan'&&verb==='resume')return '检查点已恢复，尚未自动读取。请回原面板使用原检查点和修订号显式继续。'
  return verb==='pause'?(row.kind==='upload'?'暂停已受理；正在发送的组仍会核对原回执。':'暂停已受理，保存检查点后停止后续处理。'):'操作已受理，正在核对最新状态。'
}
async function action(row:CenterRow,verb:string){
  if(!ready()||busy.value||pausePending.value||!row.actions.includes(verb))return
  if(verb==='delete'){await prepareDelete(row);return}
  if(verb==='retry-check'){showDetail(row);notice.value='在上传详情核对失败成员；成功、仍在发送或结果不明的成员不会重发。';return}
  await performAction(row,verb)
}
async function performAction(row:CenterRow,verb:string){
  if(verb==='delete')generation++
  const context=generation,ticket=++actionRequest,account=props.accountId;busy.value=row.category+':'+row.id;stop();notice.value=''
  try{const result=await api('/transfers/center/action',{method:'POST',body:{category:row.category,id:row.id,action:verb},...(verb==='recover-pending'?{timeout:150000}:{})});if(!current(context,account))return;if(verb==='delete'?!validCenterDelete(result,row):!confirmsAction(result,row))throw new Error('任务操作回执无法确认');if(verb==='delete'){if(detail.value?.id===row.id&&detail.value.category===row.category)detail.value=null;cachedDetails.value=cachedDetails.value.filter(saved=>saved.id!==row.id||saved.category!==row.category);notice.value='任务记录已删除，已下载完成的文件已保留。'}else notice.value=actionNotice(row,verb);detailRefresh.value++;void load()}
  catch(cause){if(current(context,account)){if(verb==='delete')deleteUnknown.value={...deleteUnknown.value,[detailKey(row)]:true};error.value=(cause instanceof Error?cause.message:'操作未完成')+(verb==='delete'?' 请刷新任务列表核对删除结果，不会自动重试删除。':' 请刷新核对，操作不会自动重试。');access(cause)}}
  finally{if(ticket===actionRequest)busy.value='';schedule()}
}
function operationKey(){return 'transfer-center-pause:'+props.accountId}
function rememberOperation(){try{if(pauseOperation.value)sessionStorage.setItem(operationKey(),pauseOperation.value)}catch{/* Server receipt remains queryable. */}}
async function pauseAll(repeat=false){
  if(!ready()||pausePending.value||busy.value||pauseUnknown.value&&!repeat)return
  if(!repeat){pauseOperation.value=crypto.randomUUID();pauseReceipt.value=null;rememberOperation()}
  if(!pauseOperation.value)return
  const context=generation,account=props.accountId,operation=pauseOperation.value;pausePending.value=true;pauseUnknown.value=true;stop()
  try{const result=await api<PauseReceipt>('/transfers/center/pause-all',{method:'POST',body:{operationId:operation}});if(!current(context,account))return;if(!validPauseReceipt(result,operation))throw new Error('全部暂停回执无法确认');pauseReceipt.value=result;pauseUnknown.value=result.state!=='COMPLETED';detailRefresh.value++;void load()}
  catch(cause){if(current(context,account)){pauseUnknown.value=true;error.value=(cause instanceof Error?cause.message:'暂停结果未确认')+' 请按原操作号核对；不会自动重放。';access(cause)}}
  finally{if(props.accountId===account&&pauseOperation.value===operation)pausePending.value=false;schedule()}
}
async function lookupPause(){
  if(!ready()||!pauseOperation.value||pausePending.value)return;const context=generation,account=props.accountId,operation=pauseOperation.value;pausePending.value=true
  try{const result=await api<PauseReceipt|null>('/transfers/center/pause-all/'+encodeURIComponent(operation));if(!current(context,account))return;if(result===null){pauseUnknown.value=true;notice.value='尚未查到原操作回执，可再次核对或显式提交同一操作号。';return}if(!validPauseReceipt(result,operation))throw new Error('暂停回执无法确认');pauseReceipt.value=result;pauseUnknown.value=result.state!=='COMPLETED';error.value='';void load()}
  catch(cause){if(current(context,account)){error.value=cause instanceof Error?cause.message:'回执核对未完成';access(cause)}}finally{if(props.accountId===account&&pauseOperation.value===operation)pausePending.value=false;schedule()}
}
watch([()=>props.authorized,()=>props.available,()=>props.accountId],()=>{generation++;stop();page.value=null;detail.value=null;error.value='';notice.value='';busy.value='';loading.value=false;offset.value=0;pauseReceipt.value=null;pauseOperation.value='';pauseUnknown.value=false;pausePending.value=false;try{const saved=sessionStorage.getItem(operationKey());if(saved&&/^[0-9a-f-]{36}$/.test(saved)){pauseOperation.value=saved;pauseUnknown.value=true}}catch{}void load()},{immediate:true})
watch([()=>props.authorized,()=>props.accountId],()=>{actionRequest++;scanRequest++;scanDetails.value={};scanErrors.value={};scanLoading.value='';cachedDetails.value=[];deleteUnknown.value={}})
watch([()=>props.authorized,()=>props.available,()=>props.accountId,()=>props.active],()=>clearDeleteConfirmation(),{flush:'sync'})
watch(()=>props.category,category=>{if(category&&selected.value!==categoryKind(category)){clearDeleteConfirmation();selected.value=categoryKind(category);offset.value=0;generation++;detail.value=null;void load()}})
watch([()=>props.active,()=>props.refreshVersion],()=>{clearDeleteConfirmation();generation++;stop();loading.value=false;if(ready())void load()})
onBeforeUnmount(()=>{clearDeleteConfirmation();disposed=true;generation++;scanRequest++;stop()})
</script>
<template>
  <section class="transfer-tasks" aria-label="统一任务中心">
    <div class="center-counts"><button v-for="item in statuses" :key="item.id" type="button" :class="['count-card',item.id,{selected:status===item.id}]" :aria-pressed="status===item.id" :title="item.description" @click="filter(status===item.id?'all':item.id)"><strong>{{page?.counts[item.id]??'—'}}</strong><span>{{item.label}}</span></button></div>
    <div class="center-toolbar"><div class="center-tabs" role="group" aria-label="任务类型"><button v-for="tab in tabs" :key="tab.id" type="button" :class="{selected:selected===tab.id}" :aria-pressed="selected===tab.id" @click="select(tab.id)">{{tab.label}}</button></div><div class="center-tools"><label>状态 <select :value="status" @change="filter(($event.target as HTMLSelectElement).value as CenterStatus)"><option value="all">全部状态</option><option v-for="item in statuses" :key="item.id" :value="item.id">{{item.label}}</option></select></label><button class="btn" :disabled="!ready()||loading" @click="load()">刷新</button><button class="btn" :disabled="!ready()||pausePending||!!busy||pauseUnknown" @click="pauseAll()">{{pausePending?'正在受理…':'全部暂停'}}</button></div></div>
    <p v-if="!authorized||!accountId" class="center-empty">连接 Telegram 后查看当前账号的任务。</p><p v-else-if="!available" class="notice warning">本机服务暂不可用，任务读取已暂停。</p>
    <div v-if="error" class="notice danger" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div>
    <section v-if="pauseReceipt||pauseUnknown" class="center-receipt" aria-label="全部暂停回执"><strong>全部暂停 · {{pauseReceipt?.state==='COMPLETED'?'受理结束':pauseReceipt?.state==='NEEDS_REVIEW'?'中断后待核对':'结果待核对'}}</strong><p v-if="pauseReceipt">受理 {{pauseReceipt.accepted.length}} 项 · 未确认 {{pauseReceipt.failed.length}} 项 · 处理中 / 中断待核对 {{pauseReceipt.pending.length}} 项</p><p v-if="pauseReceipt" v-for="warning in pauseReceipt.warnings" :key="warning">{{warning}}</p><ul v-if="pauseReceipt?.failed.length"><li v-for="item in pauseReceipt.failed" :key="item.category+item.id">{{item.category}} · {{item.id}}：{{item.message}}</li></ul><p><small>操作号：{{pauseOperation}}</small></p><div class="receipt-actions"><button class="btn" :disabled="pausePending||!ready()" @click="lookupPause">核对本次暂停结果</button><button v-if="pauseUnknown&&!pauseReceipt" class="btn" :disabled="pausePending||!ready()" @click="pauseAll(true)">提交同一操作号</button></div></section>
    <div class="center-table-wrap"><table class="center-table"><thead><tr><th>任务</th><th>状态 / 阶段</th><th>进度</th><th>操作</th></tr></thead><tbody>
      <tr v-if="!page?.items.length"><td colspan="4" class="center-empty">{{loading?'正在读取任务…':'当前筛选下没有任务'}}</td></tr>
      <template v-for="row in page?.items??[]" :key="row.category+':'+row.id"><tr :class="{expanded:detail?.category===row.category&&detail?.id===row.id}">
        <td class="task-name" :title="row.targetDirectory?'保存目录：'+row.targetDirectory:row.subtitle"><div class="task-title-line"><span class="kind-badge">{{row.kind==='upload'?'↑ 上传':row.kind==='download'?'↓ 下载':'扫描'}}</span><strong :title="row.title">{{row.title||'未命名任务'}}</strong></div><small :title="row.subtitle">{{row.subtitle}}</small></td>
        <td><span :class="['center-state',row.state==='CANCELLED'?'cancelled':row.statusGroup]">{{centerStateLabels[row.state]??row.state}}</span><small>{{centerPhaseLabels[row.phase]??row.phase}}</small><template v-if="row.category==='download'&&row.state==='QUEUED'&&row.phase==='RETRY_WAIT'"><small class="retry-schedule">{{row.retry?centerRetrySummary(row):'已安排自动重试，可打开详情核对时间。'}}</small><small class="retry-help">无需手动继续；暂停会取消自动重试。</small></template><small v-if="row.error" :class="['row-error',{'retry-reason':row.phase==='RETRY_WAIT'}]" :title="row.error">{{row.error}}</small></td>
        <td class="task-progress"><div class="progress-summary"><strong v-if="centerProgress(row)!==null">{{centerProgress(row)}}%</strong><span v-if="centerProgress(row)!==null&&row.totalBytes">{{formatMediaBytes(row.transferredBytes)}} / {{formatMediaBytes(row.totalBytes)}}</span><span v-else-if="centerProgress(row)===null">已观察 {{row.resolvedFiles}} 项 · 总量未知</span></div><div v-if="centerProgress(row)!==null" class="progress-track" role="progressbar" :aria-valuenow="centerProgress(row)!" aria-valuemin="0" aria-valuemax="100" :aria-label="row.kind==='upload'?'字节上传进度，正式回执另行核对':row.kind==='download'?'处理进度，下载字节与保存回执分别显示':'已处理进度'"><span :style="{width:centerProgress(row)+'%'}"></span></div><small class="progress-facts"><span v-if="row.kind==='upload'">已归档 {{row.resolvedFiles}} / {{row.totalFiles}}</span><template v-else-if="row.kind==='download'"><span>已处理 {{row.resolvedFiles}} / {{row.totalFiles}}</span><span v-if="row.skippedFiles">跳过 {{row.skippedFiles}}</span><span>写入 {{formatMediaBytes(row.writtenBytes)}}</span></template><span v-if="row.speedBytesPerSecond!==null">{{formatMediaBytes(row.speedBytesPerSecond)}}/s<span v-if="row.etaSeconds!==null"> · {{centerEta(row.etaSeconds)}}</span></span></small></td>
        <td class="task-actions"><button v-for="verb in row.actions.filter(value=>value!=='retry-check')" :key="verb" class="btn" :disabled="!!busy||pausePending||!ready()||verb==='delete'&&!!deleteUnknown[detailKey(row)]" @click="action(row,verb)">{{centerActionLabel(row,verb)}}</button><button class="btn detail-button" :id="'task-open-'+row.category+'-'+row.id" :aria-expanded="detail?.category===row.category&&detail?.id===row.id" @click="openDetail(row)">{{detail?.category===row.category&&detail?.id===row.id?'收起':'详情'}}</button></td>
      </tr></template>
    </tbody></table></div>
    <section v-for="saved in cachedDetails" :key="saved.category+saved.id" v-show="detailActive(saved)" class="center-detail-panel" :id="'task-detail-'+saved.category+'-'+saved.id" tabindex="-1" aria-label="任务详情" @keydown.esc.stop="closeDetail"><header class="detail-heading"><h3>任务详情</h3><button class="btn" @click="closeDetail">关闭详情</button></header><UploadTasks v-if="saved.category==='upload'" :focus-id="saved.detailId" :authorized="authorized" :available="available" :account-id="accountId" :active="detailActive(saved)" :refresh-version="detailRefresh" @access-error="emit('accessError',$event)"/><DownloadTasks v-else-if="saved.category==='download'" :focus-id="saved.detailId" :authorized="authorized" :available="available" :account-id="accountId" :active="detailActive(saved)" :refresh-version="detailRefresh" @access-error="emit('accessError',$event)"/><DownloadBatches v-else-if="saved.category==='batch'" :focus-id="saved.detailId" :authorized="authorized" :available="available" :account-id="accountId" :active="detailActive(saved)" :refresh-version="detailRefresh" @access-error="emit('accessError',$event)"/><RuleDownloadTasks v-else-if="saved.category==='rule-download'" :focus-id="saved.detailId" :authorized="authorized" :available="available" :account-id="accountId" :active="detailActive(saved)" :refresh-version="detailRefresh" @access-error="emit('accessError',$event)"/><div v-else class="scan-detail"><strong>{{centerScanScope(saved)}} · {{saved.title}}</strong><p>{{centerPhaseLabels[saved.phase]??saved.phase}} · {{scanState(saved)}}</p><p>已观察 / 处理 {{saved.resolvedFiles}} 项{{saved.totalFiles?'，当前清单共 '+saved.totalFiles+' 项':'，未推断尚未读取的总量'}}。</p><p v-if="saved.targetDirectory">处理位置：<code>{{saved.targetDirectory}}</code></p><p v-if="saved.error">{{saved.error}}</p><section v-if="registeredScan(saved)" class="scan-snapshot" aria-label="已登记扫描详情"><p v-if="scanLoading===detailKey(saved)" role="status">正在核对已登记的扫描详情…</p><p v-if="scanErrors[detailKey(saved)]" class="scan-read-error" role="status">{{scanErrors[detailKey(saved)]}}</p><dl v-if="scanDetails[detailKey(saved)]"><dt>记录归属</dt><dd>{{scanDetails[detailKey(saved)]!.current?'当前会话记录':'历史记录 · 只读'}}</dd><dt>检查点状态</dt><dd>{{centerStateLabels[scanDetails[detailKey(saved)]!.state]??scanDetails[detailKey(saved)]!.state}}</dd><dt>原始 scanId / runId</dt><dd><code>{{scanDetails[detailKey(saved)]!.sourceId}}</code></dd><dt>修订号</dt><dd>{{scanDetails[detailKey(saved)]!.revision}}</dd></dl><button class="btn" type="button" :disabled="scanLoading===detailKey(saved)||!ready()" @click="loadScanDetail(saved)">重新核对详情</button><p class="scan-read-note">仅在打开或手动核对时读取详情，不认领、不恢复、不执行下一步。</p></section><p>{{scanHint(saved)}}</p><details class="scan-identity"><summary>检查点与历史记录</summary><p>原检查点：<code>{{saved.detailId}}</code></p><p>历史记录：<code>{{saved.id}}</code></p></details></div></section>
    <footer class="center-footer"><span>共 {{page?.total??0}} 条 · 按最近更新排序</span><div><button class="btn" :disabled="offset===0||loading||!ready()" @click="paginate(-1)">上一页</button><span>{{pageNumber}} / {{pageCount}}</span><button class="btn" :disabled="offset+limit>=(page?.total??0)||loading||!ready()" @click="paginate(1)">下一页</button></div></footer>
